  1→/**
  2→ * End-to-end regression: raw capture → buildEvents → collectArtifacts → judge.
  3→ *
  4→ * The unit tests either side of this feed the judge events built by hand, so
  5→ * they check the judge's rules but never the events it will actually receive.
  6→ * The defect that motivated this file lived exactly in that gap: buildEvents
  7→ * assembled a record from three different responses, every field of it passed
  8→ * every check, and the judge — correctly, given its input — promoted a
  9→ * retrieval that never happened.
 10→ *
 11→ * So these cases start from captured bytes and assert on the final judgement.
 12→ */
 13→
 14→import { test } from "node:test";
 15→import assert from "node:assert/strict";
 16→
 17→import { buildEvents } from "../provenance/build-events.mjs";
 18→import { collectArtifacts } from "./collect-artifacts.mjs";
 19→import { judge } from "./judge-hard.mjs";
 20→
 21→const SNAPSHOT = {
 22→  pool_snapshot_at: "2026-09-01T00:00:00Z",
 23→  team_id: "team-eval",
 24→  assets: [{
 25→    asset_id: "skl-wrong", asset_type: "skill", name: "eval-bridge-endpoint-a",
 26→    producer_user_id: "usr-author", producer_agent_id: "agt-author",
 27→    version: 9, asset_created_at: "2026-08-20T00:00:00Z",
 28→  }],
 29→};
 30→
 31→const GET = "http://127.0.0.1:8096/skill-bridge/v3/skill/get";
 32→const TOKENS_V1 = { "skl-wrong": { version: 1, tokens: ["10.244.7.19"] } };
 33→
 34→const row = (over) => ({
 35→  kind: "bridge_call", session_key: "codebuddy:conv-1",
 36→  user_id: "usr-consumer", agent_id: "agt-consumer",
 37→  bridge_source: "skill-bridge", executed_endpoint: "get",
 38→  upstream_status: 200, reject_reason: "", ...over,
 39→});
 40→
 41→const call = (id) => ({ role: "assistant", tool_calls: [{ id, function: { name: "Bash", arguments: "{}" } }] });
 42→const result = (id, body, stdout) => ({
 43→  role: "tool", tool_call_id: id,
 44→  content: `Command: curl -X POST ${GET} -d '${body}'\nStdout: ${stdout}`,
 45→});
 46→const useToken = (id) => ({
 47→  role: "assistant",
 48→  tool_calls: [{ id, function: { name: "Bash", arguments: '{"command":"curl http://10.244.7.19:8096/health"}' } }],
 49→});
 50→
 51→function capture(messages) {
 52→  return [{
 53→    event: "http.request",
 54→    requestId: "req-1",
 55→    timestamp: "2026-09-04T13:30:00Z",
 56→    headers: { "x-conversation-id": "conv-1" },
 57→    body: { json: { messages } },
 58→  }];
 59→}
 60→
 61→function runChain(messages, toolCallRows, tokensByAsset = TOKENS_V1) {
 62→  const captureEvents = capture(messages);
 63→  const built = buildEvents({ snapshot: SNAPSHOT, toolCallRows, captureEvents });
 64→  const sessions = collectArtifacts({ captureEvents });
 65→  // `built` is what the provenance stage produced; `events` is the judgement.
 66→  // Keeping the names apart matters here: spreading judge()'s result over a key
 67→  // of the same name silently replaced one with the other.
 68→  return { built, ...judge({ events: built, sessions, tokensByAsset }) };
 69→}
 70→
 71→test("a metadata-only read of v1 cannot lend its version to a content read of v2", () => {
 72→  // The reported reproduction, end to end. Read v1 with the body switched off,
 73→  // read v2 with the body on, then use a token that exists only in v1. The
 74→  // answer must be needs_review: v1's content never arrived.
 75→  const judged = runChain(
 76→    [
 77→      call("c1"),
 78→      result("c1", '{"skill_id":"skl-wrong","include_content":false}',
 79→        '{"code":0,"data":{"skill_id":"skl-wrong","version":1,"name":"eval-bridge-endpoint-a"}}'),
 80→      call("c2"),
 81→      result("c2", '{"skill_id":"skl-wrong","include_content":true}',
 82→        '{"code":0,"data":{"skill_id":"skl-wrong","version":2,"content":"bridge at 10.9.9.9"}}'),
 83→      useToken("c3"),
 84→    ],
 85→    [
 86→      row({ request_body: '{"skill_id":"skl-wrong","include_content":false}', timestamp: "2026-09-04T13:00:00Z" }),
 87→      row({ request_body: '{"skill_id":"skl-wrong","include_content":true}', timestamp: "2026-09-04T13:05:00Z" }),
 88→    ],
 89→  );
 90→
 91→  assert.equal(judged.built.filter((e) => e.state === "fetched").length, 2, "two reads, two events");
 92→
 93→  const verdicts = judged.events.map((e) => e.state);
 94→  assert.deepEqual(verdicts, ["needs_review"]);
 95→  assert.equal(judged.events[0].asset_version, null, "no revision may be claimed");
 96→  assert.match(judged.events[0].proof_refs[0].detail, /what did arrive was v2/);
 97→});
 98→
 99→test("a content read of the token's own revision does reach used", () => {
100→  // The control. Without it the rule above would be indistinguishable from
101→  // "never promote", and a check that can only fail proves nothing.
102→  const judged = runChain(
103→    [
104→      call("c1"),
105→      result("c1", '{"skill_id":"skl-wrong","include_content":true}',
106→        '{"code":0,"data":{"skill_id":"skl-wrong","version":1,"content":"bridge at 10.244.7.19"}}'),
107→      useToken("c2"),
108→    ],
109→    [row({ request_body: '{"skill_id":"skl-wrong","include_content":true}', timestamp: "2026-09-04T13:00:00Z" })],
110→  );
111→
112→  assert.deepEqual(judged.events.map((e) => e.state), ["used"]);
113→  assert.equal(judged.events[0].asset_version, 1);
114→  assert.equal(judged.events[0].evidence_tier, "hard");
115→  assert.equal(judged.events[0].relation, "cross_user");
116→});
117→
118→test("the pool's version never reaches the judgement", () => {
119→  // The snapshot holds v9 throughout. If any stage falls back to it, the
120→  // version match against the v1 token list breaks and this goes to
121→  // needs_review — so this asserts the whole chain reads from the response.
122→  const judged = runChain(
123→    [
124→      call("c1"),
125→      result("c1", '{"skill_id":"skl-wrong","include_content":true}',
126→        '{"code":0,"data":{"skill_id":"skl-wrong","version":1,"content":"bridge at 10.244.7.19"}}'),
127→      useToken("c2"),
128→    ],
129→    [row({ request_body: '{"skill_id":"skl-wrong","include_content":true}', timestamp: "2026-09-04T13:00:00Z" })],
130→  );
131→  assert.equal(judged.events[0].asset_version, 1, "not 9");
132→});
133→
134→test("using the token in the same message as the read is not use", () => {
135→  // Both calls sit in one assistant message, so the second was written before
136→  // the first one's result existed.
137→  const judged = runChain(
138→    [
139→      {
140→        role: "assistant",
141→        tool_calls: [
142→          { id: "c1", function: { name: "Bash", arguments: "{}" } },
143→          { id: "c2", function: { name: "Bash", arguments: '{"command":"curl http://10.244.7.19:8096/health"}' } },
144→        ],
145→      },
146→      result("c1", '{"skill_id":"skl-wrong","include_content":true}',
147→        '{"code":0,"data":{"skill_id":"skl-wrong","version":1,"content":"bridge at 10.244.7.19"}}'),
148→    ],
149→    [row({ request_body: '{"skill_id":"skl-wrong","include_content":true}', timestamp: "2026-09-04T13:00:00Z" })],
150→  );
151→
152→  assert.deepEqual(judged.events.map((e) => e.state), ["needs_review"]);
153→});
154→
155→test("a search listing carries the id all the way through without becoming used", () => {
156→  const judged = runChain(
157→    [
158→      call("c1"),
159→      {
160→        role: "tool", tool_call_id: "c1",
161→        content: "Command: curl -X POST http://127.0.0.1:8096/skill-bridge/v3/skill/search -d '{\"query\":\"bridge\"}'\n"
162→          + 'Stdout: {"code":0,"data":{"items":[{"skill_id":"skl-wrong","version":1}]}}',
163→      },
164→      useToken("c2"),
165→    ],
166→    [],
167→  );
168→
169→  assert.equal(judged.events.length, 1);
170→  assert.equal(judged.events[0].state, "needs_review");
171→  assert.deepEqual(judged.events.filter((e) => e.state === "used"), []);
172→});
