/** Exit status and stderr, read out of a shell tool result envelope. */
export function outcomeOf(resultText) {
  const s = String(resultText ?? "");
  // The real CodeBuddy envelope spells the tail sections "Exit Code:" (capital
  // C) and "Signal:", after "Stderr:"; shell fixtures have used the lowercase
  // "Exit code:". Match either, and allow the negative codes the envelope can
  // carry. Matching only the lowercase spelling is why real captures always
  // read back a null exit status.
  const code = /(?:^|\n)Exit Code:\s*(-?\d+)/i.exec(s);
