test("the envelope's tail sections are not read back as stderr", () => {
  const ok = outcomeOf(envelope(0));
  assert.equal(ok.exit_code, 0);
  assert.equal(ok.stderr, "", "`(empty)` stderr reads back empty, without `Exit Code:`");

